import workcell, sys, time

TARE=121.07; TARGET=371.07

def read():
    r = workcell.call("scale", "read", "--json")
    if not r.ok:
        print("scale error", r.text); sys.exit(1)
    return r.data['gross_g']

def act(tool,*args):
    r = workcell.call(tool,*args)
    if not r.ok:
        print(tool,"error",r.text); sys.exit(1)
    print(r.text)

for step in range(120):
    g = read()
    net = g-TARE
    rem = TARGET-g
    print(f"[{step}] gross={g:.2f} net={net:.2f} rem={rem:+.2f}")
    if -0.20 <= rem <= 0.20:
        print("in tolerance")
        break
    if rem < -0.20:
        act("robot","remove")
    else:
        kind = "fine" if rem > 2.5 else "micro"
        act("robot","dose",kind)
else:
    print("max steps reached")
PY

